```

### Step 2: Set Up Your Project
Create a new directory for your project and initialize it with a `main.c` file.

```sh
mkdir snake_game
cd snake_game
touch main.c
```

### Step 3: Write the Code

Here's a basic implementation of the Snake game using SDL:

```c
#include <SDL2/SDL.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define SCREEN_WIDTH 640
#define SCREEN_HEIGHT 480
#define GRID_SIZE 20
#define SNAKE_SIZE 20

typedef struct {
    int x;
    int y;
} Point;

Point snake[100];
int snake_length = 1;
int direction = 0; // 0: up, 1: right, 2: down, 3: left
Point food;

void init_snake() {
    snake[0].x = SCREEN_WIDTH / 2;
    snake[0].y = SCREEN_HEIGHT / 2;
}

void place_food() {
    food.x = rand() % (SCREEN_WIDTH / GRID_SIZE) * GRID_SIZE;
    food.y = rand() % (SCREEN_HEIGHT / GRID_SIZE) * GRID_SIZE;
}

void draw_snake(SDL_Renderer *renderer) {
    SDL_SetRenderDrawColor(renderer, 0, 255, 0, 255);
    for (int i = 0; i < snake_length; i++) {
        SDL_Rect rect = {snake[i].x, snake[i].y, SNAKE_SIZE, SNAKE_SIZE};
        SDL_RenderFillRect(renderer, &rect);
    }
}

void draw_food(SDL_Renderer *renderer) {
    SDL_SetRenderDrawColor(renderer, 255, 0, 0, 255);
    SDL_Rect rect = {food.x, food.y, SNAKE_SIZE, SNAKE_SIZE};
    SDL_RenderFillRect(renderer, &rect);
}

void move_snake() {
    Point new_head = {snake[0].x, snake[0].y};

    switch (direction) {
        case 0: // up
            new_head.y -= GRID_SIZE;
            break;
        case 1: // right
            new_head.x += GRID_SIZE;
            break;
        case 2: // down
            new_head.y += GRID_SIZE;
            break;
        case 3: // left
            new_head.x -= GRID_SIZE;
            break;
    }

    for (int i = snake_length - 1; i > 0; i--) {
        snake[i] = snake[i - 1];
    }
    snake[0] = new_head;

    if (new_head.x == food.x && new_head.y == food.y) {
        snake_length++;
        place_food();
    }
}

int check_collision() {
    for (int i = 1; i < snake_length; i++) {
        if (snake[i].x == snake[0].x && snake[i].y == snake[0].y) {
            return 1;
        }
    }
    return 0;
}

int main(int argc, char* argv[]) {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("Failed to initialize SDL: %s\n", SDL_GetError());
        return 1;
    }

    SDL_Window *window = SDL_CreateWindow("Snake Game", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    if (!window) {
        printf("Failed to create window: %s\n", SDL_GetError());
        SDL_Quit();
        return 1;
    }

    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        printf("Failed to create renderer: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    init_snake();
    place_food();

    bool running = true;
    SDL_Event event;
    Uint32 start_time, end_time, frame_duration = 100; // 10 FPS

    while (running) {
        start_time = SDL_GetTicks();

        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            } else if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_UP:
                        if (direction != 2) direction = 0;
                        break;
                    case SDLK_DOWN:
                        if (direction != 0) direction = 2;
                        break;
                    case SDLK_LEFT:
                        if (direction != 1) direction = 3;
                        break;
                    case SDLK_RIGHT:
                        if (direction != 3) direction = 1;
                        break;
                }
            }
        }

        move_snake();

        if (check_collision()) {
            running = false;
        }

        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
        SDL_RenderClear(renderer);

        draw_snake(renderer);
        draw_food(renderer);

        SDL_RenderPresent(renderer);

        end_time = SDL_GetTicks();
        int delay = frame_duration - (end_time - start_time);
        if (delay > 0) {
            SDL_Delay(delay);
        }
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

### Explanation:
1. **Initialization**: Initialize SDL and create a window and renderer.
2. **Game Logic**:
   - `init_snake`: Initializes the snake at the center of the screen.
   - `place_food`: Randomly places food on the grid.
